typedef struct { void (*execute)(void *ctx); void (*undo)(void *ctx); void *ctx; } command_t;

static void insert_text(void *ctx) { doc_insert((doc_t *)ctx, 0, "x"); }
static void delete_last(void *ctx) { doc_delete((doc_t *)ctx, 0, 1); }

static command_t history[64]; static size_t top = 0;
static void run(command_t c) { c.execute(c.ctx); history[top++] = c; }
static void unwind(void) { command_t c = history[--top]; c.undo(c.ctx); }
